function defSources(u){
  const A = army(), F = factionOf(A) || {}, out = [], seen = new Set();
  const put = x => { if(seen.has(x.key + '|' + x.grp)) return; seen.add(x.key + '|' + x.grp); const o = defBoxesOf(x.key); if(o && (o.d || o.dnc)) out.push(Object.assign(x, { o })); };
  for(const r of u.rules || []){ if(!/\d/.test(r) || D.rules[r]) continue; const t = dmCoreText(r); if(t) put({ grp:'core', name:r, a:'rule', v:r, key:DM_KEY.c(r, t), rl:r }); }
  for(const r of F.armyRules || []){ const own = hasRule(u, r.name) || !!dmGrantOf(A, u, r.name), o = defBoxesOf(DM_KEY.r(r));
    const reach = !own && A.units.some(x => x !== u && hasRule(x, r.name)) && ((o || {}).d || []).some(b => b.reach && dmReaches(b.reach, u));
    if(own || reach) put({ grp:'army', name:r.name, a:'rule', v:r.name, key:DM_KEY.r(r), reachOnly:reach, holders:reach ? A.units.filter(x => hasRule(x, r.name)) : null }); }
  for(const r of unitDetRules(u)) put({ grp:'army', name:r.name, a:'rule', v:r.name, key:DM_KEY.r(r) });
  for(const ab of u.abilities || []) if(!naReason(ab)) put({ grp:'unit', name:ab.name, a:'ability', v:abilityKey(ab), key:DM_KEY.a(ab), ab, src:u });
  for(const x of A.units) if(x !== u) for(const ab of x.abilities || []) if(!naReason(ab)) put({ grp:'other', name:ab.name, a:'unit', v:x.id, key:DM_KEY.a(ab), ab, src:x });
  // (the core stratagems, every unit's, are on the Stratagems tab, as for the footnotes)
  for(const s of allStratagems().filter(s => s.src !== 'Core')){ const o = defBoxesOf(DM_KEY.s(s)); if(!o) continue;
    const mine = o.dreach ? matches(o.dreach, u) && A.units.some(x => x !== u && canTarget(s, x)) : canTarget(s, u);
    if(mine) put({ grp:'strat', name:s.name, a:'strat', v:s.id, key:DM_KEY.s(s), s, cp:s.cp }); }
  return out;
}

function defenceItems(u){
  const out = [];
  for(const S of defSources(u)){
    for(const b of S.o.d || []){
      // (a box given to friendly units: where it reaches this one; the unit's own for itself only where it is an aura, 22.01, not "other";
      // an enemy unit's attacks made worse: every unit of the list. Another unit's other boxes are its own)
      if(b.foe ? false : S.reachOnly ? !(b.reach && dmReaches(b.reach, u)) : b.reach ? !dmReaches(b.reach, u) || (S.grp === 'unit' && b.notSelf) : S.grp === 'other') continue;
      // (an invulnerable save or Save characteristic the list printed into its stats, marked as from this rule, the other models' as good or
      // better already: Arcane Shield's 4+ InSv on its Rubric Marines, as a footnote leaves out what is in the weapons)
      const inStats = (k, p) => (u.stats || []).some(r => r.from && String(r.from[k] || '').split(/\s*,\s*/).includes(S.name)) && (u.stats || []).every(r => (r.from && String(r.from[k] || '').split(/\s*,\s*/).includes(S.name)) || parseInt(r[k], 10) <= p);
      const tIn = () => (u.stats || []).some(r => r.from && String(r.from.T || '').split(/\s*,\s*/).includes(S.name));
      if(!b.pick && b.df.length && b.df.every(([id, p]) => (id === 'inv' && inStats('InSv', p)) || (id === 'svSet' && inStats('Sv', p)) || (id === 't' && !(b.on || []).length && tIn()))) continue;
      const x = defLineOf(S, b, u); if(x) out.push(x);
    }
    // (its words about attacks against it no defence reads: "not counted here: see the rule", once; not another unit's)
    if(S.grp !== 'other' && (S.o.dnc || []).length) out.push({ a:S.a, v:S.v, name:S.name, cp:S.cp || '', who:S.ab && S.ab.who && u.leads ? S.ab.who : '', when:'', text:FN_NC, key:S.key, ncLine:true, rl:S.rl || '' });
  }
  // (a Feel No Pain on its Rules line that another of its lines says with its condition or its model: Aegis of the Emperor's "against mortal
  // wounds", New Recruit's starred "Feel No Pain 5+*"; Trajann's own: not said twice)
  const fnpOf = x => x.box ? (x.box.pick ? x.box.pick.flatMap(p => p.df) : x.box.df).filter(([id]) => /^fnp/.test(id)).map(([, p]) => p) : [];
  // (a Feel No Pain on its Rules line that another of its lines says with its words: one of its own abilities ("the bearer has the Feel No Pain
  // 3+ ability against Psychic Attacks", Collar of Khorne), or, for New Recruit's starred "Feel No Pain 5+*", any rule ("against mortal wounds",
  // Aegis of the Emperor): not said twice, never without its condition)
  const res = out.filter(x => !(x.rl && /^feel no pain/i.test(x.rl) && fnpOf(x).some(v => out.some(y => y !== x && !y.rl && (y.a === 'ability' || /\*$/.test(x.rl)) && fnpOf(y).includes(v)))));
  // (the one model of an attached unit a rule of its Rules line is on: partialRules)
  for(const x of res) if(x.rl && !x.who){ const w = partialWho(u, x.rl); if(w) x.who = w; }
  for(const x of res) x.t = x.rl && !x.when && x.text === x.name ? x.name : [x.cp ? x.cp + 'CP' : '', x.name + ':', x.when ? x.when + ':' : '', x.text, x.from ? '(' + x.from + ')' : ''].filter(Boolean).join(' ');
  return res;
}

function defLineOf(S, b, u){
  const E = WH_EFFECTS, on = b.on || [], wn = [].concat(u.ranged || [], u.melee || []).flatMap(w => [w.name, w.group]).filter(Boolean).map(x => String(x).toLowerCase());
  // (a keyword or wargear of the unit the box needs: the unit's keywords and weapons say it)
  if(on.some(([id, p]) => ((id === 'selfKw' || id === 'itIs') && !hasKw(u, p)) || (id === 'selfGear' && !p.every(g => wn.some(n => n.startsWith(String(g).toLowerCase())))))) return null;
  const giver = S.grp === 'other' ? (S.ab && S.ab.who && S.src.leads && charsOf(S.src).some(c => c.name === S.ab.who) ? S.ab.who : S.src.short || S.src.name)
    : S.holders ? 'a unit with ' + S.name : '';
  const own = S.grp === 'unit' && b.mark === 'aura';
  const said = ([id, p]) => E.DCOND[id] ? E.DCOND[id].label(p) : fnCond(id, p, u, giver, own);
  const quoted = ([id]) => !!(E.COND[id] && E.COND[id].quoted);
  const ph = S.s && (S.s.phases || []).length === PHASES.length ? 'Any phase' : S.s && (S.s.phases || []).length ? S.s.phases.map((p, i) => (T => (T === 'your' ? 'Your ' : T === 'opp' ? 'Your opponent’s ' : i ? 'the ' : '') + PHASE_NAME[p] + ' phase')(phTurn(S.s, p))).join(' or ') : '';
  const df = b.pick ? b.pick.flatMap(p => p.df) : b.df;
  const kind = DEF_KIND[b.kind] && !defKindSaid(df, b.kind) ? DEF_KIND[b.kind] : '';
  // (every condition said; a box whose only conditions are GW's words, quoted, says "If (see the rule)", as a footnote does)
  const cond = on.length && on.every(quoted) ? FN_IF : on.map(said).join(' · ');
  const when = [ph, kind, cond].filter(Boolean).join(', ');
  const sc = b.scope || {}, models = sc.models && sc.models !== 'model' ? sc.models + ' models: ' : '';
  const text = models + (b.pick ? 'one of: ' + b.pick.map(p => E.dfLabel(p.df)).join(' · ') : E.dfLabel(b.df));
  return { a:S.a, v:S.v, name:S.name, cp:S.cp || '', who:S.ab && S.ab.who && u.leads && S.grp === 'unit' ? S.ab.who : '', when, text, from:S.grp === 'other' ? giver : '', riled:on.some(x => x[0] === 'riled'), box:b, key:S.key, rl:S.rl || '' };
}

function defLine(x, u){
  const who = x.who ? '<i class="sc">' + esc(x.who) + '</i> ' : '';
  const ar = x.riled && alwaysRiled(u), when = x.when ? esc(x.when) : '';
  const w = ar ? when.replace(/^(.*?)Riled up/, (m, pre) => pre + 'Riled up (' + ar + ')') : when;
  // (a rule of its Rules line that is its defence, "Feel No Pain 5+": its name)
  if(x.rl && !w && x.text === x.name) return who + '<b>' + linkTo(x.a, x.v, x.name) + '</b>';
  return who + (x.cp ? '<b class="cpb">' + esc(x.cp) + 'CP</b> ' : '') + '<b>' + linkTo(x.a, x.v, x.name) + ':</b> ' + (w ? '<span class="tw">' + w + ':</span> ' : '') + esc(x.text) +
    (x.from ? ' <span class="from">(' + linkTo('unit', x.v, x.from) + ')</span>' : '');
}

function readingsOfUnit(u, ab){
  const named = m => m.from === ab.name || String(ab.text || '').includes('**' + m.from);
  const attack = ['mods', 'aura'].flatMap(k => (u[k] || []).filter(named)), guard = (u.guard || []).filter(named);
  const words = ms => ms.map(m => [m.note, m.when, m.selfWhen, JSON.stringify(m.set || {}), JSON.stringify(m.calc || {})].join(' ')).join(' | ');
  const marks = [...(u.stats || []), ...(u.ranged || []), ...(u.melee || [])].flatMap(x => Object.entries(x.from || {}).filter(([, v]) => [].concat(v).includes(ab.name)).map(([k]) => k));
  const fnpLine = (u.rules || []).filter(r => /^feel no pain \d\+/i.test(r) && String(ab.text || '').toLowerCase().includes(r.toLowerCase().replace(/\*$/, '')));
  return { attack, guard, marks,
    attackSaid:words(attack) + ' | ' + marks.map(k => /^(A|S|D)$/.test(k) ? '"' + k + '":"+' : k === 'AP' ? '+1 AP' : k === 'WS' || k === 'BS' ? k + ' improved' : k).join(' | ') + ' | ' + JSON.stringify(ab.defCalc || {}),
    defSaid:[fnpLine.join(' '), marks.includes('InSv') ? 'InSv' : ''].filter(Boolean).join(' | ') };
}

function abilityGaps(u, ab){
  const found = [];
  if(ab.na) return found;
  const r = readingsOfUnit(u, ab), all = r.attackSaid + ' | ' + r.defSaid;
  const hasKw = k => (u.kw || []).some(x => x.toLowerCase() === k.toLowerCase() || x.toLowerCase() === 'faction: ' + k.toLowerCase());
  for(const { s, pre } of sentenceCtx(ab.text)){
    // (an option for a keyword the unit does not have: "If this model has the TZEENTCH keyword" on a Daemon Prince of Khorne)
    const kwIf = /\b[Ii]f this (?:model|unit) has the ([A-Z][A-Z’' -]+?) keyword/.exec(s);
    if(kwIf && !hasKw(kwIf[1].trim())) continue;
    const b = bonusOf(s), miss = [];
    let check = null;
    // (an attack bonus: the unit's footnotes and the Damage tab's boxes are data.js BOXES, made from these words by script; verify/evidence.js
    // G4 holds every attack effect of them to a box or to its words listed as not counted. Only the defence side is a reading)
    // (a defence is said by a "When targeted" reading, not by an attack footnote that happens to say "damage" or "AP")
    const bd = boxDefences(ab);
    if(bd.nc.some(q => q.includes(s.slice(0, 40)))) continue;
    const dmiss = b.def.filter(id => !bd.ids.has(id) && !covers(id, r.defSaid + ' | ' + r.marks.join(' | '), DEFENCE));
    if(dmiss.length){ check = check || 'defence'; miss.push(...dmiss); }
    if(check) found.push({ check, sentence:s, bonus:[...new Set(miss)] });
  }
  return found;
}

function resolveArmies(armies, sheets, order, factions, opts){
  opts = opts || {}; factions = factions || {};
  var ROWS = ['stats', 'ranged', 'melee', 'abilities'], READ = [];
  var FPK = ["gistOf","readOf","readBy","listWhy"], RHIDE = ['readOf', 'readBy', 'listWhy'].filter(function(k){ return (opts.keep || []).indexOf(k) < 0; });
  var HIDE = ['ds', 'over', 'of', 'why', 'own', 'faction', 'bsId'].concat(FPK, ["points","composition","options","aiStatus"]).filter(function(k){ return (opts.keep || []).indexOf(k) < 0; });
  function put(o, x){ for(var k in x) if(HIDE.indexOf(k) < 0){ if(x[k] === null) delete o[k]; else o[k] = x[k]; } return o; }
  function copy(x){ return JSON.parse(JSON.stringify(x)); }   // each unit its own copy of a datasheet's values
  function sorted(o, keys){ var out = {}, i, k; for(i = 0; i < keys.length; i++) if(keys[i] in o) out[keys[i]] = o[keys[i]]; for(k in o) if(!(k in out)) out[k] = o[k]; return out; }
  function rowOf(part, kind, name, group){ var rows = (part && part[kind]) || [], j; for(j = 0; j < rows.length; j++) if(rows[j].name === name && (group === undefined || (rows[j].group || null) === group)) return j; return -1; }
  function find(parts, kind, r){
    var name = kind === 'stats' ? String(r.name).replace(/ ×\d+$/, '') : r.name, i, j;
    // (a row by its name and, where its datasheet has two rows of the name, the group the entry names: the Bloodthirster's "strike" of its
    // Great axe of Khorne, not of its Axe of Khorne)
    var g = kind === 'stats' ? undefined : r.group;
    if(r.of !== undefined) return { p:r.of, j:rowOf(parts[r.of], kind, name, g) };
    for(i = 0; i < parts.length; i++) if(parts[i].name === r.who && (j = rowOf(parts[i], kind, name, g)) >= 0) return { p:i, j:j };
    for(i = 0; i < parts.length; i++) if((j = rowOf(parts[i], kind, name, g)) >= 0) return { p:i, j:j };
    return { p:-1, j:-1 };
  }
  // names alike in case and apostrophe (New Recruit's "Martial Ka'tah", Wahapedia's "Martial Ka’tah")
  function nm(s){ return String(s).toLowerCase().replace(/[’‘]/g, "'"); }
  function has(list, x){ for(var i = 0; i < (list || []).length; i++) if(nm(list[i]) === nm(x)) return true; return false; }
  function meets(n, u){ return !n || (!n.all || n.all.every(function(k){ return has(u.kw, k); })) && (!n.any || n.any.some(function(k){ return has(u.kw, k); }))
    && !(n.none || []).some(function(k){ return has(u.kw, k); }) && (!n.rule || n.rule.some(function(r){ return has(u.rules, r); })); }
  // the readings of one kind a unit has: the rows' (each with where it is from, for the trace), then the entry's
  function readings(a, u, out, ids, parts, kind){
    var F = factions[a.faction] || {}, dets = (a.detachments || []).map(function(d){ return (F.detachments || {})[d]; }).filter(Boolean), t = [], enh = null;
    function take(x, at){ ((x && x[kind]) || []).forEach(function(m, j){ t.push({ m:m, at:at, j:j }); }); }
    (F.armyRules || []).forEach(function(r){ if(has(out.rules, r.name)) take(r, null); });
    parts.forEach(function(p, i){ take(p, ids[i]); });
    dets.forEach(function(d){ (d.enhancements || []).forEach(function(e){ if(!enh && (e.name === out.enhancement || e.name === out.upgrade)) take(enh = e, null); }); });
    dets.forEach(function(d){ [d.rule].concat(d.moreRules || []).forEach(function(r){ if(r && meets(r.needs, out)) take(r, null); }); });
    var own = u[kind], list = [];
    if(own === null) list = [];
    else if(!own) list = t;
    else if(own.some(function(x){ return typeof x === 'string'; })) own.forEach(function(x, e){ if(typeof x !== 'string') list.push({ m:x, at:null, e:e }); else t.forEach(function(y, i){ if(y.m.from === x) list.push(i === t.findIndex(function(z){ return z.m.from === x; }) ? Object.assign({ e:e }, y) : y); }); });
    else list = t.concat(own.map(function(x, e){ return { m:x, at:null, e:e }; }));
    return list.map(function(y, n){ var m = copy(y.m); RHIDE.forEach(function(k){ delete m[k]; }); if(opts.trace) opts.trace(a, u, kind, n, y.at, y.at ? y.j : -1, y.e); return m; });
  }
  return armies.map(function(a){
    return Object.assign({}, a, { units:a.units.map(function(u){
      if(!u.ds) return u;
      var ids = [].concat(u.ds), parts = ids.map(function(id){ if(!sheets[id]) throw new Error('data.js: ' + a.id + '/' + u.id + ' names no datasheet ' + id); return sheets[id]; });
      var out = {}, k, rest = {};
      for(k in parts[0]) if(ROWS.indexOf(k) < 0 && READ.indexOf(k) < 0 && HIDE.indexOf(k) < 0) out[k] = copy(parts[0][k]);
      for(k in u) if(ROWS.indexOf(k) < 0 && READ.indexOf(k) < 0) rest[k] = u[k];
      put(out, rest); if(u.over) put(out, u.over);
      ROWS.forEach(function(kind){
        var list;
        if(kind in u){ if(u[kind] === null){ delete out[kind]; return; } list = u[kind]; }
        else if(parts.length === 1 && parts[0][kind]) list = parts[0][kind].map(function(r){ return { name:r.name }; });
        else return;
        out[kind] = list.map(function(r, n){
          var at = find(parts, kind, r);
          if(at.j < 0){ if(opts.trace) opts.trace(a, u, kind, n, null, -1); return put({}, r); }
          if(opts.trace) opts.trace(a, u, kind, n, ids[at.p], at.j);
          var ds = parts[at.p][kind][at.j], row = put({}, copy(ds)); put(row, r); if(r.over) put(row, r.over);
          // (for --expand: the datasheet's own value of a stat a rule of the list changed, own, so --write gives it back)
          if((kind === 'stats' || kind === 'ranged' || kind === 'melee') && r.from && (opts.keep || []).indexOf('own') >= 0){ var own = {}, f; for(f in r.from) if(f in ds && ds[f] !== r[f]) own[f] = ds[f]; for(f in own){ row.own = own; break; } }
          return sorted(row, order[kind] || []);
        });
      });
      READ.forEach(function(kind){ var l = readings(a, u, out, ids, parts, kind); if(l.length) out[kind] = l; });
      return sorted(out, order.unit || []);
    }) });
  });
}
